export const SOURCES: CourseSource[] = [
  { id: 'optimism-maier-seligman', title: 'Maier & Seligman · 2016 · Learned helplessness at fifty: insights from neuroscience (Psychological Review)', url: 'https://doi.org/10.1037/rev0000033', type: 'research', finding: 'The review concludes that the original 1967 theory got the mechanism backward. Passivity after prolonged, uncontrollable shock is an unlearned default response (mediated by the dorsal raphe nucleus). What animals learn is control: the medial prefrontal cortex detects control and then inhibits that default. The authors speculate that this has implications for treating depression.', limitation: 'Based mainly on animal research; how it applies to people facing everyday setbacks is the authors’ speculation, not something this review tested. Abstract read (via Europe PMC).' },
  { id: 'optimism-sweeney', title: 'Sweeney, Anderson & Bailey · 1986 · Attributional style in depression: a meta-analytic review (Journal of Personality and Social Psychology)', url: 'https://doi.org/10.1037/0022-3514.50.5.974', type: 'research', finding: 'Across 104 studies with nearly 15,000 participants, explaining negative events by internal, stable and global causes was reliably associated with depression scores. Explaining positive events by external, unstable and specific causes was also associated with depression, but more weakly. The patterns held for student and psychiatric samples and for real and hypothetical events.', limitation: 'Correlational: it shows an association, not that explanatory style causes depression. An older review. Abstract read (via Europe PMC).' },
  { id: 'optimism-malouff', title: 'Malouff & Schutte · 2017 · Can psychological interventions increase optimism? A meta-analysis (Journal of Positive Psychology)', url: 'https://doi.org/10.1080/17439760.2016.1221122', type: 'research', finding: '29 randomized controlled trials with 3,319 participants: interventions increased optimism with an average effect of g = 0.41. Effects were larger for the Best Possible Self exercise, in-person delivery, active control groups, assessment within one day of the intervention and completer (rather than intention-to-treat) analyses.', limitation: 'Larger effects in short-term measures and completer analyses suggest that lasting change is less certain. Abstract read (University of New England repository).' },
  { id: 'optimism-rozanski', title: 'Rozanski et al. · 2019 · Association of optimism with cardiovascular events and all-cause mortality (JAMA Network Open)', url: 'https://jamanetwork.com/journals/jamanetworkopen/fullarticle/2752100', type: 'research', finding: 'Meta-analysis of 15 studies with 229,391 participants and a mean follow-up of 13.8 years. Higher optimism was associated with a lower risk of cardiovascular events (pooled relative risk 0.65, 95% CI 0.51–0.78; 10 studies) and of death from any cause (0.86, 0.80–0.92; 9 studies).', limitation: 'All included studies were observational, with high heterogeneity and different optimism measures and adjustments. It shows association, not that optimism causes better health or that raising optimism would lower risk. Key results and limitations read.' },
  { id: 'optimism-prp-meta', title: 'Brunwasser, Gillham & Kim · 2009 · A meta-analytic review of the Penn Resiliency Program’s effect on depressive symptoms (Journal of Consulting and Clinical Psychology)', url: 'https://ppc.sas.upenn.edu/sites/default/files/prpmetaanalyticreview.pdf', type: 'research', finding: '17 controlled evaluations with 2,498 young people aged 8–18. Compared with no intervention, participants reported fewer depressive symptoms after the program (d = 0.11), at 6–8 months (d = 0.21) and at 12 months (d = 0.20). Compared with active control conditions there was no significant difference, and the effect on depression diagnoses was not significant.', limitation: 'Small effects in young people taking a structured group program; it does not test adults using ABC skills on their own. Author-hosted PDF (abstract and summary sections) read.' },
  { id: 'optimism-penn-prp', title: 'Positive Psychology Center, University of Pennsylvania · Resilience in children (Penn Resiliency Program)', url: 'https://ppc.sas.upenn.edu/research/resilience-children', type: 'guidance', finding: 'The Penn Resiliency Program is built around Ellis’s ABC model: students learn to detect inaccurate thoughts, evaluate their accuracy and challenge negative beliefs by considering other interpretations, alongside assertiveness, problem solving and relaxation. It runs as 12 ninety-minute or 18–24 sixty-minute sessions. The page cites about 20 controlled studies and acknowledges some inconsistent findings.', limitation: 'Written by the program’s developers. The independent meta-analysis found small effects and no advantage over other active programs.' },
  { id: 'optimism-hofmann', title: 'Hofmann et al. · 2012 · The efficacy of cognitive behavioral therapy: a review of meta-analyses (Cognitive Therapy and Research)', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC3584580/', type: 'research', finding: 'The review covered 269 meta-analyses of CBT. The strongest support was for CBT of anxiety disorders, somatoform disorders, bulimia, anger control problems and general stress. Of 11 reviews comparing response rates, CBT had higher response rates than the comparison conditions in 7 and lower in 1.', limitation: 'About CBT delivered as therapy, not self-help in an app. The authors note too few high-quality studies for some conditions and no meta-analyses for groups such as ethnic minorities or low-income samples. Full-text summary read.' },
  { id: 'optimism-smernoff', title: 'Smernoff, Mitnik, Kolodner & Lev-ari · 2015 · The effects of “The Work” meditation (Byron Katie) on psychological symptoms and quality of life: a pilot clinical study (EXPLORE)', url: 'https://www.sciencedirect.com/science/article/abs/pii/S1550830714002067', type: 'research', finding: '197 people from a non-clinical sample took a nine-day course in The Work. Depression, anxiety, happiness and quality-of-life scores improved significantly (all p < .001) after the course and at six months. 164 completed the post-course measures and 102 the six-month follow-up.', limitation: 'A single-group pilot study with no control group and high dropout; the authors call for randomized trials. Abstract read.' },
  { id: 'optimism-seligman-exercises', title: 'Seligman, Steen, Park & Peterson · 2005 · Positive psychology progress: empirical validation of interventions (American Psychologist)', url: 'https://greatergood.berkeley.edu/images/uploads/Seligman-PosPsychProgress.pdf', type: 'research', finding: 'Online, randomized, placebo-controlled study: 577 adults randomized, 411 completed all follow-ups. All groups, including placebo, felt better right after the one-week exercise. People who wrote three things that went well each day and why, for one week, were happier and less depressed than at baseline from one month on, and stayed so at three and six months; using signature strengths in a new way showed a similar pattern. People who kept practicing beyond the week were the ones who kept benefiting.', limitation: 'Self-selected, mostly well-educated, white and mildly depressed volunteers who wanted to be happier. Later replications found smaller or less specific effects. Full text read (copy hosted by the Greater Good Science Center).' },
  { id: 'optimism-mongrain', title: 'Mongrain & Anselmo-Matthews · 2012 · Do positive psychology exercises work? A replication of Seligman et al. (2005) (Journal of Clinical Psychology)', url: 'https://doi.org/10.1002/jclp.21839', type: 'research', finding: 'Using the original method with an improved control and an added “positive placebo”, three good things and using signature strengths produced lasting increases in happiness, but so did the positive placebo. The exercises did not beat the control condition for changes in depression.', limitation: 'Abstract read only (via Europe PMC); sample details not reviewed. The authors suggest the benefit may come from a general effect of thinking about positive, self-relevant information.' },
  { id: 'optimism-bolier', title: 'Bolier et al. · 2013 · Positive psychology interventions: a meta-analysis of randomized controlled studies (BMC Public Health)', url: 'https://link.springer.com/article/10.1186/1471-2458-13-119', type: 'research', finding: '39 studies with 6,139 participants. Right after the programs: subjective well-being d = 0.34, psychological well-being d = 0.20, depression d = 0.23. At 3–6 months: 0.22, 0.16 and 0.17, with the effect on depression no longer significant.', limitation: 'None of the studies met all quality criteria (20 were rated low quality) and there was evidence of publication bias. It pools many different exercises, not three good things alone. Abstract and results read.' },
  { id: 'optimism-wood', title: 'Wood, Perunovic & Lee · 2009 · Positive self-statements: power for some, peril for others (Psychological Science)', url: 'https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x', type: 'research', finding: 'A survey showed that people often use and trust positive self-statements. In two experiments, people with low self-esteem who repeated a statement about being a lovable person ended up in a worse mood than controls, while people with high self-esteem felt only slightly better.', limitation: 'Short experiments measuring mood in the moment; abstract read only. It does not show that every form of positive thinking is harmful.' },
  { id: 'optimism-nhs-cbt', title: 'NHS · Cognitive behavioural therapy (CBT)', url: 'https://www.nhs.uk/mental-health/talking-therapies-medicine-treatments/talking-therapies-and-counselling/cognitive-behavioural-therapy-cbt/overview/', type: 'guidance', finding: 'The NHS describes CBT as a talking therapy in which a therapist helps you change how you think and act. It is used for depression, anxiety disorders, PTSD and other conditions, usually over 5 to 15 sessions; if symptoms do not improve, more sessions or other treatments may be needed. The page links to urgent mental health help.', limitation: 'Access details are specific to England. The self-help exercises in this course are not a substitute for CBT with a trained therapist; in an emergency, call your local emergency number.' },
  { id: 'optimism-distortions', title: 'Psychology Tools · Cognitive distortions: unhelpful thinking styles (extended)', url: 'https://www.psychologytools.com/resource/cognitive-distortions-unhelpful-thinking-styles-extended', type: 'guidance', finding: 'Describes 20 unhelpful thinking styles, including all-or-nothing thinking, catastrophizing, disqualifying the positive, mental filter, mind reading, overgeneralization, personalizing and “should” statements, and traces the idea to Aaron Beck’s work in the 1960s, later popularized by David Burns.', limitation: 'A clinician resource summarizing common categories; the categories overlap and are not a diagnosis.' },
  { id: 'optimism-seligman-book', title: 'Martin E. P. Seligman · Learned Optimism: How to Change Your Mind and Your Life (1990; Vintage edition 2006)', url: 'https://www.penguinrandomhouse.com/books/163862/learned-optimism-by-martin-e-p-seligman-phd/', type: 'technique', finding: 'Seligman describes explanatory style (how permanent, pervasive and personal your explanations for setbacks are) and teaches readers to replace give-up habits with more constructive explanations. His ABCDE method extends Albert Ellis’s ABC model with Disputation and Energization.', limitation: 'Publisher’s page read; the ABCDE and three Ps steps here are retold from secondary descriptions and from the closely related skills in Penn’s resilience programs, not from the book’s text. Programs built on these ideas show small effects; the book has not been tested as a treatment and does not replace one.' },
  { id: 'optimism-ellis', title: 'Albert Ellis · Emotional disturbance and its treatment in a nutshell (Albert Ellis Institute)', url: 'https://albertellis.org/wp-content/uploads/2021/09/Emotional-Disturbance-and-Its-Treatment-in-a-Nutshell-ABCs-.pdf', type: 'technique', finding: 'Ellis explains the ABC model he first presented in 1956: activating events (A) lead to emotional and behavioral consequences (C) through beliefs (B). Rigid demands (“musts” and “shoulds”) and catastrophic conclusions fuel disturbance; disputing them (D) cognitively, emotionally and behaviorally leads to new, more flexible beliefs based on preferences (E).', limitation: 'A description of rational emotive behavior therapy by its founder, not a research review; REBT outcome research was not reviewed for this course.' },
  { id: 'optimism-beck-thought-record', title: 'Judith S. Beck · Thought Record Worksheet, from Cognitive Behavior Therapy: Basics and Beyond, 3rd edition (Beck Institute, 2020)', url: 'https://beckinstitute.org/wp-content/uploads/2021/08/Thought-Record-Worksheet.pdf', type: 'technique', finding: 'The worksheet has columns for date and time, situation, automatic thoughts with a belief rating (0–100%), emotions with intensity, cognitive distortion, adaptive response and outcome. Its guiding questions ask about evidence for and against the thought, other explanations, the worst, best and most realistic outcomes, what you would tell a friend, and the effect of keeping versus changing the thought.', limitation: 'A clinical worksheet designed for use in CBT. Used alone it is self-help, and self-guided use is less studied than therapist-led CBT.' },
  { id: 'optimism-the-work', title: 'Byron Katie · Do The Work: instructions (thework.com)', url: 'https://thework.com/instruction-the-work-byron-katie/', type: 'technique', finding: 'Katie’s instructions: write stressful judgments about a person or situation in short, simple sentences; then ask four questions of each (whether it is true, whether you can be absolutely sure, how you react when you believe it, who you would be without it); then turn the thought around (to yourself, to the other, to the opposite) and find at least three genuine examples of each turnaround.', limitation: 'The author’s own instructions; the research base is limited to early, uncontrolled studies.' },
  { id: 'optimism-mrt', title: 'Reivich, Seligman & McBride · 2011 · Master Resilience Training in the U.S. Army (American Psychologist)', url: 'https://ppc.sas.upenn.edu/sites/default/files/mrtinarmyjan2011.pdf', type: 'technique', finding: 'Describes a resilience course for Army sergeants adapted from the Penn Resiliency Program: the ABC model and explanatory style, thinking traps (such as overgeneralizing, jumping to conclusions and a “me” style), deeper “iceberg” beliefs, putting it in perspective (worst, best and most likely outcome, then a plan), and hunting the good stuff, a daily record of good things.', limitation: 'A program description. At publication only trainees’ immediate feedback was reported, and controlled evaluations were still under way. Author-hosted PDF read.' },
  { id: 'optimism-ggia-three-good-things', title: 'Greater Good in Action (UC Berkeley) · Three Good Things', url: 'https://ggia.berkeley.edu/practice/three-good-things', type: 'technique', finding: 'Instructions: spend about ten minutes a day for at least a week writing three things that went well, with details, how they made you feel and what caused them. The page cites the 2005 Seligman study and later studies in several countries reporting better well-being and less pessimism, depression or anxiety.', limitation: 'A university practice guide that summarizes favorable studies and says more research is needed across cultures. Replications suggest effects are small and not always specific to this exercise.' },
];

